package id.matin.nusatv;

import android.app.*;
import android.os.Build;
import android.widget.EditText;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import com.lagradost.cloudstream3.*;

/** Native dialogs accept both D-pad/OK and touch; all provider work is off the UI thread. */
final class CloudUi {
 final MainActivity a;final ExecutorService worker=Executors.newSingleThreadExecutor();CloudRuntime runtime;
 interface Work<T>{T run()throws Exception;} interface Done<T>{void accept(T value)throws Exception;}
 CloudUi(MainActivity host){a=host;}
 CloudResolver.Session active;CloudResolver resolver;String playbackId="";JSONArray activeLinks=new JSONArray();long requestId=0;Future<?> resolveJob;ProgressDialog resolving;
 void cancelPlayback(){requestId++;if(active!=null)active.cancelled=true;active=null;playbackId="";if(resolveJob!=null)resolveJob.cancel(true);if(resolving!=null){resolving.dismiss();resolving=null;}}
 void close(){cancelPlayback();worker.shutdownNow();if(runtime!=null)runtime.close();}
 <T> void task(String title,Work<T> work,Done<T> done){ProgressDialog wait=new ProgressDialog(a);wait.setMessage(title);wait.setCancelable(false);wait.show();worker.execute(()->{try{T value=work.run();a.handler.post(()->{if(a.isFinishing()||a.isDestroyed())return;wait.dismiss();try{done.accept(value);}catch(Exception e){error(e);}});}catch(Throwable e){a.handler.post(()->{if(a.isFinishing()||a.isDestroyed())return;wait.dismiss();error(e);});}});}
 void error(Throwable e){String text=e.getMessage();if(text==null||text.trim().isEmpty())text=e.getClass().getSimpleName();new AlertDialog.Builder(a).setTitle("Film / Cloudstream").setMessage(text.length()>240?text.substring(0,240):text).setPositiveButton("Tutup",null).show();}
 JSONArray installed(){try{return new JSONArray(a.prefs.getString("cloudstream-installed","[]"));}catch(Exception e){return new JSONArray();}}
 void show(){if(Build.VERSION.SDK_INT<26){new AlertDialog.Builder(a).setTitle("Film & Cloudstream").setMessage("Percobaan ekstensi memerlukan Android 8.0 atau lebih baru. IPTV ELIO TV tetap dapat digunakan.").setPositiveButton("Tutup",null).show();return;}
  new AlertDialog.Builder(a).setTitle("Film & Cloudstream · Percobaan").setItems(new String[]{"Buka provider terpasang","Tambahkan repo Cloudstream","Kelola ekstensi terpasang","Tentang dukungan ekstensi","Demo API · Big Buck Bunny"},(d,w)->{if(w==0)openProviders();else if(w==1)addRepo();else if(w==2)manage();else if(w==4)task("Memuat demo…",()->{if(runtime==null)runtime=new CloudRuntime(a);runtime.demo();return runtime.providers();},rows->{new AlertDialog.Builder(a).setTitle("Demo offline").setItems(new String[]{"Putar video demo","Uji sumber kosong → provider cadangan"},(dd,ww)->{String name=ww==0?"ELIO Demo · Big Buck Bunny":"ELIO Demo · Sumber kosong";for(MainAPI p:rows)if(p.getName().equals(name)){provider(p);return;}error(new Exception("Provider demo belum dimuat"));}).setNegativeButton("Tutup",null).show();});else new AlertDialog.Builder(a).setTitle("Dukungan percobaan").setMessage("Repo berisi daftar ekstensi, bukan video langsung. Pasang hanya ekstensi yang Anda percaya dan gunakan sumber dengan izin yang sesuai. Ekstensi berjalan dengan izin internet ELIO TV.\n\nPencarian, daftar awal, detail film/episode dan sumber video didukung melalui API Cloudstream. Kompatibilitas setiap ekstensi berbeda. Ekstensi dengan resource, torrent, login khusus, CAPTCHA dan sumber DRM belum didukung.\n\nSumber kosong atau seluruh link gagal akan mencoba maksimal 4 provider terpasang lainnya. Judul dan tahun harus sama; serial juga harus cocok musim/episode. Anime atau metadata tidak lengkap perlu dipilih manual.\n\nTidak ada ekstensi yang dipasang otomatis. Subtitle provider belum diterapkan; player tetap dapat memakai subtitle bawaan video.").setPositiveButton("Tutup",null).show();}).setNegativeButton("Kembali",null).show();
 }
 void addRepo(){EditText field=new EditText(a);field.setSingleLine(true);field.setInputType(17);field.setHint("https://…/repo.json");field.setText(a.prefs.getString("cloudstream-last-repo","https://raw.githubusercontent.com/Asm0d3usX/CloudX-V2/builds/repo.json"));new AlertDialog.Builder(a).setTitle("Tambahkan repo Cloudstream").setMessage("Masukkan alamat HTTPS repo.json. Daftar ekstensi akan ditampilkan sebelum pemasangan.").setView(field).setPositiveButton("Lihat repo",(d,w)->{String url=field.getText().toString().trim();task("Membaca repo…",()->{JSONObject repo=CloudRepository.manifest(new String(CloudRepository.fetch(url,CloudRepository.JSON_LIMIT),"UTF-8"));JSONArray rows=new JSONArray();HashSet<String> seen=new HashSet<>();JSONArray lists=repo.getJSONArray("pluginLists");for(int i=0;i<lists.length();i++){JSONArray list=CloudRepository.plugins(new String(CloudRepository.fetch(lists.getString(i),CloudRepository.JSON_LIMIT),"UTF-8"));for(int j=0;j<list.length();j++){JSONObject p=list.getJSONObject(j);if(seen.add(p.getString("url")))rows.put(p);}}if(rows.length()>500)throw new Exception("Terlalu banyak ekstensi");repo.put("entries",rows);return repo;},repo->{a.prefs.edit().putString("cloudstream-last-repo",url).apply();showRepo(repo);});}).setNegativeButton("Batal",null).show();}
 void showRepo(JSONObject repo)throws Exception{JSONArray entries=repo.getJSONArray("entries");String[] names=new String[entries.length()];for(int i=0;i<names.length;i++){JSONObject p=entries.getJSONObject(i);names[i]=p.optString("name")+" · "+p.optString("language","?")+(p.optInt("status",1)==0?" · tidak tersedia":"");}new AlertDialog.Builder(a).setTitle(repo.optString("name","Repo Cloudstream")).setItems(names,(d,w)->{try{JSONObject info=entries.getJSONObject(w);if(info.optInt("status",1)==0){error(new Exception("Provider ditandai tidak tersedia oleh pengelola repo"));return;}new AlertDialog.Builder(a).setTitle("Pasang "+info.optString("name")+"?").setMessage(info.optString("description")+"\n\nEkstensi berisi kode pihak ketiga yang berjalan dengan izin aplikasi. Pasang hanya jika Anda mempercayai pengelola dan sumbernya.\n\nSumber: "+info.optString("repositoryUrl",info.optString("url"))).setPositiveButton("Pasang",(dd,ww)->task("Memasang ekstensi…",()->{if(runtime==null)runtime=new CloudRuntime(a);return runtime.install(info);},record->{JSONArray old=installed(),next=new JSONArray();for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).optString("id").equals(record.getString("id")))next.put(old.getJSONObject(i));next.put(record);a.prefs.edit().putString("cloudstream-installed",next.toString()).apply();new AlertDialog.Builder(a).setTitle("Ekstensi tersimpan").setMessage("Pilih Buka provider terpasang untuk menjalankan dan mengecek kompatibilitasnya.").setPositiveButton("Buka provider",(x,y)->openProviders()).setNegativeButton("Tutup",null).show();})).setNegativeButton("Batal",null).show();}catch(Exception e){error(e);}}).setNegativeButton("Kembali",(d,w)->show()).show();}
 void openProviders(){JSONArray records=installed();if(records.length()==0){new AlertDialog.Builder(a).setTitle("Belum ada ekstensi").setMessage("Tambahkan repo, lalu pilih ekstensi untuk dipasang.").setPositiveButton("Tambahkan repo",(d,w)->addRepo()).setNegativeButton("Tutup",null).show();return;}task("Memuat provider…",()->{if(runtime==null)runtime=new CloudRuntime(a);ArrayList<String> errors=new ArrayList<>();for(int i=0;i<records.length();i++)try{runtime.load(records.getJSONObject(i));}catch(Exception e){errors.add(records.getJSONObject(i).optString("name")+": "+e.getMessage());}List<MainAPI> providers=runtime.providers();if(providers.isEmpty())throw new Exception(errors.isEmpty()?"Ekstensi tidak mendaftarkan provider":android.text.TextUtils.join("\n",errors));return providers;},providers->{String[] names=new String[providers.size()];for(int i=0;i<names.length;i++)names[i]=providers.get(i).getName();new AlertDialog.Builder(a).setTitle("Provider film").setItems(names,(d,w)->provider(providers.get(w))).setNegativeButton("Kembali",(d,w)->show()).show();});}
 void provider(MainAPI api){new AlertDialog.Builder(a).setTitle(api.getName()).setItems(new String[]{"Cari judul","Daftar awal provider"},(d,w)->{if(w==0){EditText q=new EditText(a);q.setSingleLine(true);q.setHint("Judul film atau serial");new AlertDialog.Builder(a).setTitle("Cari · "+api.getName()).setView(q).setPositiveButton("Cari",(dd,ww)->{String text=q.getText().toString().trim();if(text.isEmpty())return;task("Mencari judul…",()->runtime.search(api,text),rows->results(api,rows));}).setNegativeButton("Batal",null).show();}else task("Memuat daftar…",()->runtime.home(api),rows->results(api,rows));}).setNegativeButton("Kembali",(d,w)->openProviders()).show();}
 void results(MainAPI api,List<SearchResponse> rows){if(rows.isEmpty()){error(new Exception("Belum ada hasil dari provider ini. Coba pencarian judul atau provider lain."));return;}int count=Math.min(rows.size(),150);String[] names=new String[count];for(int i=0;i<count;i++)names[i]=rows.get(i).getName();new AlertDialog.Builder(a).setTitle(api.getName()+" · "+count+" judul").setItems(names,(d,w)->task("Memuat detail…",()->runtime.detail(api,rows.get(w).getUrl()),detail->detail(api,detail))).setNegativeButton("Kembali",(d,w)->provider(api)).show();}
 void detail(MainAPI api,LoadResponse item){if(item==null){error(new Exception("Detail belum tersedia"));return;}String desc=(item.getYear()==null?"":item.getYear()+"\n")+(item.getPlot()==null?"":item.getPlot());new AlertDialog.Builder(a).setTitle(item.getName()).setMessage(desc.length()>1800?desc.substring(0,1800):desc).setPositiveButton("Tonton",(d,w)->watch(api,item)).setNegativeButton("Kembali",(d,w)->provider(api)).show();}
 void watch(MainAPI api,LoadResponse item){if(item instanceof MovieLoadResponse)resolve(api,item,null,item.getName());else{List<Episode> episodes=runtime.episodes(item);if(episodes.isEmpty()){error(new Exception("Jenis konten atau daftar episode belum didukung"));return;}String[] names=new String[episodes.size()];for(int i=0;i<names.length;i++){Episode e=episodes.get(i);names[i]=(e.getSeason()==null?"":"S"+e.getSeason()+" ")+(e.getEpisode()==null?"":"E"+e.getEpisode()+" ")+(e.getName()==null?"Episode "+(i+1):e.getName());}new AlertDialog.Builder(a).setTitle("Pilih episode").setItems(names,(dd,ww)->resolve(api,item,episodes.get(ww),item.getName()+" · "+names[ww])).setNegativeButton("Batal",null).show();}}
 void resolve(MainAPI api,LoadResponse item,Episode episode,String title){cancelPlayback();active=new CloudResolver.Session(api,item,episode,title);resolver=new CloudResolver(runtime);resolveActive(0);}
 boolean playbackFailed(String id,long position){if(active==null||active.cancelled||!playbackId.equals(id))return false;resolver.failedLinks(active,activeLinks);resolveActive(position);return true;}
 void acceptSource(CloudResolver.Session session,long token,CloudResolver.Result result,long position){
  if(token!=requestId||session.cancelled||!a.foreground||a.isFinishing()||a.isDestroyed())return;
  try{activeLinks=result.links;a.playCloudVideo(session.title,result.provider.getName(),result.links,position);playbackId=a.current().id;if(result.provider!=session.initial)a.message("Sumber cadangan: "+result.provider.getName());}catch(Exception e){error(e);}
 }
 void offerSource(CloudResolver.Session session,long token,CloudResolver.Result result,long position){
  if(result.candidate==null){acceptSource(session,token,result,position);return;}
  LoadResponse item=result.candidate;
  String year=item.getYear()==null?"Tahun belum tersedia":String.valueOf(item.getYear());
  String plot=item.getPlot()==null?"":item.getPlot();if(plot.length()>500)plot=plot.substring(0,500)+"…";
  new AlertDialog.Builder(a).setTitle("Cocokkan film cadangan")
   .setMessage("Sumber awal tidak menghasilkan video. Provider lain punya judul yang sama, tetapi tahun belum lengkap. Pastikan ini film yang Anda maksud.\n\n"+item.getName()+" · "+year+"\n"+result.provider.getName()+"\n\n"+plot)
   .setPositiveButton("Ya, putar",(d,w)->acceptSource(session,token,result,position))
   .setNeutralButton("Cari sumber lain",(d,w)->{if(token==requestId&&!session.cancelled){resolver.failedLinks(session,result.links);resolveActive(position);}})
   .setNegativeButton("Batal",(d,w)->{if(token==requestId){cancelPlayback();if(a.playing)a.cloudResolveStopped("Pemilihan sumber dibatalkan");}})
   .setOnCancelListener(d->{if(token==requestId){cancelPlayback();if(a.playing)a.cloudResolveStopped("Pemilihan sumber dibatalkan");}}).show();
 }
 void resolveActive(long position){
  final CloudResolver.Session session=active;final long token=++requestId;
  resolving=new ProgressDialog(a);final ProgressDialog wait=resolving;wait.setMessage("Mencari sumber video…\nJika kosong/error, mencoba provider terpasang lain dengan judul dan tahun yang sama.");wait.setCancelable(true);wait.setOnCancelListener(d->{boolean wasPlaying=!playbackId.isEmpty();cancelPlayback();if(wasPlaying)a.cloudResolveStopped("Pencarian sumber dibatalkan");a.message("Pencarian sumber dibatalkan");});wait.setButton(android.content.DialogInterface.BUTTON_NEGATIVE,"Batal",(d,w)->wait.cancel());wait.show();
  resolveJob=worker.submit(()->{try{CloudResolver.Result result=resolver.resolve(session);a.handler.post(()->{if(token!=requestId||session.cancelled||a.isFinishing()||a.isDestroyed())return;wait.dismiss();resolving=null;if(!a.foreground){cancelPlayback();return;}offerSource(session,token,result,position);});}catch(Throwable e){a.handler.post(()->{if(token!=requestId||session.cancelled||a.isFinishing()||a.isDestroyed())return;wait.dismiss();resolving=null;if(a.foreground){if(!playbackId.isEmpty())a.cloudResolveStopped("Tidak ada sumber film cadangan yang cocok");error(e);}});}});
 }
 void manage(){JSONArray records=installed();if(records.length()==0){error(new Exception("Belum ada ekstensi terpasang"));return;}String[] names=new String[records.length()];for(int i=0;i<names.length;i++)names[i]=records.optJSONObject(i).optString("name");new AlertDialog.Builder(a).setTitle("Kelola ekstensi").setItems(names,(d,w)->new AlertDialog.Builder(a).setTitle(names[w]).setMessage("Hapus ekstensi dari ELIO TV? Provider yang sudah dimuat akan dilepas setelah aplikasi dibuka ulang.").setPositiveButton("Hapus",(dd,ww)->{try{JSONArray next=new JSONArray();JSONObject record=records.getJSONObject(w);for(int i=0;i<records.length();i++)if(i!=w)next.put(records.getJSONObject(i));a.prefs.edit().putString("cloudstream-installed",next.toString()).apply();String id=record.getString("id");if(id.matches("[a-f0-9]{64}"))new java.io.File(a.getFilesDir(),"cloudstream/"+id+".cs3").delete();a.message("Ekstensi dihapus · buka ulang aplikasi");}catch(Exception e){error(e);}}).setNegativeButton("Batal",null).show()).setNegativeButton("Kembali",(d,w)->show()).show();}
}
